CREATE VIEW mart_taste_affinity_v1 AS SELECT n.GameKey, n.GameID, n.GameTitle, n.PlayStatusName, n.explicit_preference_score, n.explicit_preference_percentile, n.avg_favorite_similarity, n.avg_lower_similarity, n.preference_margin, n.similarity_margin_percentile, CASE  WHEN ((n.similarity_margin_percentile IS NULL)) THEN (NULL) ELSE round(((0.50 * n.explicit_preference_percentile) + (0.50 * n.similarity_margin_percentile)), 2) END AS taste_affinity_score, CASE  WHEN ((n.similarity_margin_percentile IS NULL)) THEN ('Insufficient classification metadata') ELSE 'Scored' END AS taste_affinity_status, n.playability_adjustment, n.hard_exclusion_flag, n.exclusion_reason FROM vw_recommendation_normalized AS n;
